#!/bin/bash
set -e

SSH_DIR="/root/.ssh"
KEY_SOURCE="/certmanager-data/ssh/id_ed25519.pub"

mkdir -p "$SSH_DIR"
chmod 700 "$SSH_DIR"

# Wait for the public key to appear (generated by certmanager on first start)
echo "Waiting for SSH public key from certmanager..."
for i in $(seq 1 60); do
    if [ -f "$KEY_SOURCE" ]; then
        cp "$KEY_SOURCE" "$SSH_DIR/authorized_keys"
        chmod 600 "$SSH_DIR/authorized_keys"
        echo "SSH key installed from $KEY_SOURCE"
        break
    fi
    sleep 2
done

if [ ! -f "$SSH_DIR/authorized_keys" ]; then
    echo "WARNING: No SSH key found after 120s. SSH auth may fail."
fi

# Exec into systemd as PID 1
exec /lib/systemd/systemd
